namespace sv_8c24e53c26d641a293972a66bd737940.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        var doctors = new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Patel",
            "Dr. Williams"
        };
        return Task.FromResult(doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        var slots = new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        };
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient info and appointment selection against server-side rules.
    /// Returns a dictionary of field name -> error message for any validation failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_8c24e53c26d641a293972a66bd737940.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    <h3>Step 1: Patient Information</h3>

    <div class="mb-3">
        <label class="form-label" for="patientName">Patient Name</label>
        <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
        <ValidationMessage For="() => Model.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="email">Email</label>
        <InputText id="email" class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="() => Model.Email" />
        @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("Email")))
        {
            <div class="validation-message">@_serverErrors["Email"]</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label" for="phone">Phone</label>
        <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="insurance">Insurance Provider</label>
        <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => Model.InsuranceProvider" />
    </div>

    @if (!_showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @if (_showStep2)
    {
        <h3 class="mt-4">Step 2: Appointment Details</h3>

        <div class="mb-3">
            <label class="form-label" for="doctor">Preferred Doctor</label>
            <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor" @bind-Value:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in _doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.Doctor" />
            @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("Doctor")))
            {
                <div class="validation-message">@_serverErrors["Doctor"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="date">Date</label>
            <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" @bind-Value:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="() => Model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="timeSlot">Time Slot</label>
            <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in _timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.TimeSlot" />
            @if (!string.IsNullOrEmpty(_serverErrors.GetValueOrDefault("TimeSlot")))
            {
                <div class="validation-message">@_serverErrors["TimeSlot"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="reason">Reason for Visit</label>
            <InputTextArea id="reason" class="form-control" @bind-Value="Model.Reason" rows="3" />
            <ValidationMessage For="() => Model.Reason" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability" disabled="@_isSubmitting">
            Check Availability
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!_availabilityChecked || _hasServerErrors || _isSubmitting)">
            Book Appointment
        </button>

        @if (_availabilityChecked && !_hasServerErrors)
        {
            <div class="alert alert-success mt-3">Availability confirmed! Click "Book Appointment" to finalize.</div>
        }
    }

    @if (_booked)
    {
        <div class="alert alert-success mt-3"><strong>Appointment booked successfully!</strong></div>
    }
</EditForm>

@code {
    private AppointmentModel Model { get; set; } = new();

    private bool _showStep2;
    private bool _availabilityChecked;
    private bool _isSubmitting;
    private bool _booked;
    private bool _hasServerErrors => _serverErrors.Count > 0;

    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _serverErrors = new();

    private EditContext? _editContext;

    protected override void OnInitialized()
    {
        _editContext = new EditContext(Model);
    }

    private async Task ProceedToStep2()
    {
        _editContext = new EditContext(Model);
        var isValid = _editContext.Validate();

        // Only check step 1 fields
        var step1Valid = !string.IsNullOrWhiteSpace(Model.PatientName)
            && !string.IsNullOrWhiteSpace(Model.Email)
            && new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(Model.Email)
            && !string.IsNullOrWhiteSpace(Model.Phone)
            && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (step1Valid)
        {
            _doctors = await AppointmentSvc.GetDoctorsAsync();
            _showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        _availabilityChecked = false;
        _serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _availabilityChecked = false;
        _isSubmitting = true;

        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.Doctor ?? "",
                Model.TimeSlot ?? "");

            _serverErrors = errors;
            _availabilityChecked = true;
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private void HandleSubmit()
    {
        if (!_hasServerErrors && _availabilityChecked)
        {
            _booked = true;
        }
    }

    public class AppointmentModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required")]
        public string PatientName { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format")]
        public string Email { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required")]
        public string Phone { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required")]
        public string InsuranceProvider { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required")]
        public string? Doctor { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required")]
        [FutureDate(ErrorMessage = "Date must be in the future")]
        public DateTime? AppointmentDate { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required")]
        public string? TimeSlot { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason is required")]
        [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason must be 500 characters or less")]
        public string? Reason { get; set; }
    }

    public class FutureDateAttribute : System.ComponentModel.DataAnnotations.ValidationAttribute
    {
        protected override System.ComponentModel.DataAnnotations.ValidationResult? IsValid(
            object? value, System.ComponentModel.DataAnnotations.ValidationContext validationContext)
        {
            if (value is DateTime date && date.Date <= DateTime.Today)
            {
                return new System.ComponentModel.DataAnnotations.ValidationResult(ErrorMessage);
            }
            return System.ComponentModel.DataAnnotations.ValidationResult.Success;
        }
    }
}

